import json
def frag(head, deps):
    return head
L8=[50,52,53,54,55,56,58,59,71,74,76,77,87,90,91,95,97,98,99,100,102,103,104,106,107,108,112,116,119,120,121,122,124,125,139,142,154,158,159,162,164,166,167,168,169,170,171,172,173,174,175,179,180,185,186,187,188,191,192,205,207,208,209,220]
recs=[{"n":n,"grade":"L8","note":""} for n in L8]
corr101={"n":101,"grade":"L1","note":"'figure' in 'make a woman figure my avatar' is written as the verb of a nonfinite clause, but it is the noun that heads 'a woman figure', so the nominal is split and the command loses its object.",
"sop":"@c1 syntax.clause form=imperative discourse="Please" verb="make" complement=$n1 complement=$n2
@n1 syntax.nominal dependent="a" dependent="woman" head="figure"
@n2 syntax.nominal dependent="my" head="avatar"
@r1 syntax.relation marker="because" from=$c1 to=$k1
@n3 syntax.nominal head="that"
@c2 syntax.clause form=declarative verb="is"
@c3 syntax.clause form=declarative modifier="how" verb="know" modifier="here" subject=$n4 complement=$n5
@n4 syntax.nominal head="people"
@n5 syntax.nominal head="me"
@k1 syntax.coordination conjunction="and" conjunct=$c2 conjunct=$c4
@n6 syntax.nominal head="I"
@c4 syntax.clause form=declarative auxiliary="do" negation="not" verb="want" subject=$n6
@n7 syntax.nominal head="it"
@r2 syntax.relation marker="to" from=$c4 to=$c5
@c5 syntax.clause form=nonfinite verb="change" subject=$n7
@r3 syntax.relation from=$c2 to=$c3"}
corr165={"n":165,"grade":"L2","note":"'not' in 'not only for the diagram I have open right now' is held in 'discourse', so its place as the negation of the last 'for' phrase is lost.",
"sop":"@n1 syntax.nominal head="I"
@c1 syntax.clause form=declarative verb="want" subject=$n1
@n2 syntax.nominal dependent="my" head="avatar"
@r1 syntax.relation marker="to" from=$c1 to=$c2
@c2 syntax.clause form=nonfinite verb="be" negation="not" modifier="only" modifier="on" subject=$n2 complement=$n3
@n3 syntax.nominal dependent="an" dependent="older" head="man"
@r2 syntax.relation marker="for" from=$c2 to=$n4
@n4 syntax.nominal dependent="every" head="session"
@r3 syntax.relation marker="from" from=$c2 to=$n5
@n5 syntax.nominal head="now"
@r4 syntax.relation marker="for" from=$c2 to=$n6
@n6 syntax.nominal dependent="the" head="diagram"
@n7 syntax.nominal head="I"
@c3 syntax.clause form=declarative verb="have" modifier="open" modifier="right" modifier="now" subject=$n7
@r5 syntax.relation from=$n6 to=$c3"}
recs.append(corr101); recs.append(corr165)
recs.sort(key=lambda r: r["n"])
with open('/tmp/judge/p2.jsonl','w') as f:
    for r in recs: f.write(json.dumps(r)+"
")
print(len(recs), [r["n"] for r in recs])
EOF

